SELECT txn_type, CASE WHEN amount >= 4000 THEN 'high' WHEN amount >= 600 THEN 'mid' ELSE 'low' END AS amount_bucket, SUM(CASE WHEN txn_type = 'DEBIT' THEN amount ELSE 0 END) AS debit_amount, ROUND((100 * SUM(CASE WHEN merchant = '7-Eleven' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_7_eleven FROM transactions GROUP BY txn_type, CASE WHEN amount >= 4000 THEN 'high' WHEN amount >= 600 THEN 'mid' ELSE 'low' END HAVING SUM(CASE WHEN txn_type = 'DEBIT' THEN amount ELSE 0 END) > 21 ORDER BY txn_type;
